  "upgrade.providerConfirmNote": "Perubahan paket memerlukan konfirmasi dari penyedia penagihan. Perbedaan harga, prorata, dan tanggal efektif harus ditampilkan sebelum Anda menyetujui perubahan. Peningkatan versi tidak boleh membuat langganan kedua secara bersamaan.",
