  "exports.eyebrow": "Data",
  "exports.title": "Ekspor & cadangan",
  "exports.subtitleStart": "Pengunduhan selalu dibatasi hingga",
  "exports.subtitleRest": ". Setiap file diberi label dengan nama bisnis dan tanggal pembuatannya.",
  "exports.createBusinessFirst": "Buat bisnis terlebih dahulu — ekspor adalah milik bisnis, bukan milik aplikasi.",
  "exports.lockedTitle": "Ekspor CSV dan Excel adalah fitur Bisnis",
  "exports.lockedDesc": "Ruang kerja Anda termasuk dalam paket Essentials. Bisnis menambahkan ekspor CSV dan Excel, penilaian stok, produk dan staf tanpa batas, pemasok, pembelian dan bundel.",
  "exports.seeBusiness": "Lihat apa saja yang termasuk dalam Bisnis",
  "exports.whatTheseAre": "Apa file-file ini",
  "exports.about1": "Setiap kumpulan data hadir sebagai CSV atau buku kerja Excel sebenarnya (.xlsx) — buku kerja inventaris lengkap hanya untuk Excel, dengan satu lembar per kumpulan data. File CSV dibuka di Excel, Numbers, Google Sheets dan sebagian besar aplikasi stok. Teks UTF-8, tanda kutip koma, jeda baris dalam catatan, dan angka nol di depan dalam kode semuanya dipertahankan, dan sel yang dimulai seperti rumus dinetralkan sehingga spreadsheet membukanya sebagai teks.",
  "exports.about2": "Dalam file Excel, SKU, UPC, ISBN, dan kode batang adalah sel teks — tidak pernah berupa notasi ilmiah dan tidak pernah dipangkas angka nol — dengan lebar kolom, filter header, dan format mata uang atau kuantitas yang diterapkan. Buku kerja inventaris lengkap menyimpan produk, tingkat stok, lokasi, dan pergerakan pada lembar terpisah.",
  "exports.about3": "Ekspor yang sangat besar berhenti pada 20.000 baris per kumpulan data — ketika hal itu terjadi, nama file menyatakan demikian (terpotong-20000), sehingga sebagian file tidak pernah lolos secara lengkap.",
  "exports.about4": "Cadangan adalah cuplikan data Anda, bukan pemulihan sekali klik. Memulihkannya adalah pekerjaan manual yang harus ditinjau terlebih dahulu, jadi simpanlah file dengan aman — belum ada apa pun di aplikasi yang dapat membuat ulang bisnis yang dihapus darinya. Pencadangan kode aplikasi dan platform Base44 ditangani secara terpisah dari file-file ini.",
  "exports.about5": "Foto dan lampiran dicantumkan sebagai tautan tersimpannya — file gambar itu sendiri tidak dimasukkan ke dalam unduhan.",
  "exports.backupTitle": "Cadangan penuh",
  "exports.backupDesc": "Satu file berisi produk, lokasi, tingkat stok, buku besar pergerakan lengkap, pemasok, pembelian, pesanan, pengembalian, penghitungan, dan daftar bisnis ini — ditambah pengaturan profilnya. Simpan di tempat yang Anda kendalikan.",
  "exports.backupIncludes1": "Produk, kode, biaya dan catatan",
  "exports.backupIncludes2": "Lokasi dan jumlah per lokasi",
  "exports.backupIncludes3": "Setiap gerakan, dengan aktor dan waktu",
  "exports.backupIncludes4": "Pembelian, pemesanan, pengembalian, dan penghitungan",
