  "import.title": "Pusat impor",
  "import.subtitleStart": "Tiga operasi spreadsheet terpisah, sehingga koreksi harga tidak akan pernah sampai sebagai tanda terima stok. Semuanya masuk",
  "import.subtitleRest": "saja, dan tidak ada yang ditulis sampai masa kering berlalu.",
  "import.createBusinessFirst": "Ciptakan bisnis terlebih dahulu — produk impor adalah milik bisnis.",
  "import.createBusinessFirstShort": "Buatlah bisnis terlebih dahulu.",
  "import.whatEachDoes": "Apa yang dilakukan setiap operasi",
  "import.createTitle": "Buat produk baru",
  "import.createDesc": "menambahkan baris yang belum ada dalam katalog. Duplikat SKU dan kode batang yang sudah digunakan dilewati, dan stok pembuka dapat mendarat di lokasi yang Anda pilih sebagai tanda terima.",
  "import.updateTitle": "Perbarui produk yang ada",
  "import.updateDesc": "mencocokkan setiap baris dengan SKU atau ID rekaman dan menunjukkan nilai lama di samping nilai baru yang diusulkan. Sel kosong membiarkan nilai yang disimpan kecuali Anda meminta sel kosong dibersihkan, dan jumlahnya tidak pernah disentuh.",
  "import.receiveModeTitle": "Menerima stok",
  "import.receiveModeDesc": "menambahkan jumlah kedatangan ke satu lokasi dan menulis tanda terima ke buku besar pergerakan untuk setiap baris. Setiap batch ditandai, sehingga lembar yang sama tidak dapat diterima dua kali.",
  "import.excelNote": "Buku kerja Excel (.xlsx) dibaca secara langsung — pilih lembar kerja dan kolom yang cocok untuk Anda. Kode tetap utuh: UPC yang disimpan sebagai teks mempertahankan angka dan angka nol di depannya. Baris yang tidak dapat diimpor dicantumkan beserta alasannya",
