  "valuation.footnote": "Nilai biaya menggunakan biaya unit setiap produk saat ini, sehingga menerima dengan harga baru akan menilai ulang keseluruhan rak. Unit yang disimpan masih dihitung di sini — unit tersebut tersedia, hanya dijanjikan untuk dipesan. Uang yang hilang tidak pernah dianggap nol; biarkan satu kolom kosong sampai angkanya diketahui.",
