  "print.templateIsBusiness": "{label} adalah fitur Bisnis",
  "print.supplierBlockedDesc": "Dokumen pemasok disertakan dengan rencana Bisnis — pemasok, pembelian, dan pesanan pembelian. Semua yang Anda miliki sekarang terus berfungsi.",
  "print.seeBusiness": "Lihat apa saja yang termasuk dalam Bisnis",
  "print.nothingToPrint": "Belum ada yang perlu dicetak",
  "print.pickOrderHint": "Pilih pesanan pembelian dari daftar untuk melihat pratinjau dokumen.",
  "print.pickCustomerOrderHint": "Pilih pesanan pelanggan dari daftar untuk melihat pratinjau dokumen.",
  "print.pickReturnHint": "Pilih pengembalian yang dicatat dari daftar untuk melihat pratinjau dokumen.",
  "print.chooseStyleHint": "Pilih gaya, lalu pilih produk dari daftar. Pratinjau menunjukkan dengan tepat apa yang keluar dari printer.",
  "print.howToReach": "Cara menjangkau printer Anda",
  "print.howIntro": "Aplikasi ini terhubung ke printer yang Anda miliki — ini bukan printer itu sendiri. Ada empat cara untuk mencapai salah satunya, dan label dicetak pada kedua rencana di atas salah satu rencana tersebut. Slip pengepakan, pesanan pembelian, dokumen dan laporan pemasok hanya berlaku untuk Bisnis, apa pun hubungannya.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Dari halaman ini, di desktop Chrome atau Edge dan di Android Chrome: pilih printer label Anda dan label langsung menuju ke sana. Ini tidak berfungsi di iOS Safari — di iPhone, pencetakan Bluetooth hadir dengan aplikasi seluler. Printer yang hanya menggunakan bahasa Zebra ZPL atau Brother sendiri tidak akan memahami label yang dikirimkan halaman ini; yang diperiksa dengan printer asli sebelum disebut berfungsi.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Instal printer di Wi-Fi toko Anda, lalu gunakan tombol Cetak — printer ini mencetak melalui printer yang diinstal di komputer ini, melalui jaringan toko. Di iPhone, AirPrint sudah terpasang: printer AirPrint pada Wi-Fi yang sama hanya muncul di lembar cetak, tidak memerlukan kabel dan aplikasi, dan aplikasi tidak memerlukan kode khusus AirPrint. Printer harus mendukung AirPrint (kebanyakan printer baru mendukungnya) dan telepon serta printer harus berada pada Wi-Fi yang sama.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Sambungkan printer ke jaringan toko Anda dengan kabel Ethernet, pasang di komputer, dan cetak melalui tombol Cetak. Ethernet adalah jalur desktop dan komputer — iPhone tidak menggunakan kabel Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Hubungkan printer ke komputer dengan kabelnya dan gunakan tombol Cetak — printer akan mencetak melalui printer yang terpasang di sana. Pada ponsel Android dengan kabel OTG USB, tombol USB di atas berkomunikasi langsung ke printer. iPhone tidak dapat mencetak melalui USB secara langsung — tidak ada WebUSB di sana — jadi gunakan Wi-Fi / AirPrint, atau Bluetooth dari aplikasi seluler.",
  "print.howCordsLead": "Kabel masih melayani iPhone, satu langkah dihilangkan.",
  "print.howCordsBody": "Printer USB yang dicolokkan ke komputer toko, atau printer Ethernet yang disambungkan ke jaringan, muncul di iPhone Anda melalui toko Wi-Fi (AirPrint / printer bersama) — kabelnya menempatkan printer di jaringan dengan kuat, dan telepon menjangkaunya secara nirkabel.",
  "print.howOfflineLead": "Jika internet terputus,",
  "print.howOfflineBody": "label dan dokumen yang sudah ada di halaman ini masih tercetak — tombol Cetak, Label PDF, Bluetooth, dan USB tidak memerlukan sambungan. Yang memerlukan internet adalah memuat halaman dan produknya terlebih dahulu. Mode offline penuh (bekerja di aplikasi tanpa koneksi sama sekali) adalah versi terpisah yang lebih besar dan tidak diklaim di sini.",
