  "settings.cancelTerms.appleLink": "Instruksi pembatalan Apple",
  "settings.cancelTerms.googlePlayLink": "Google Petunjuk pembatalan pemutaran",
  "settings.cancelTerms.graceTitle": "Setelah periode pembayaran Anda berakhir — tenggang waktu 15 hari, lalu penghapusan:",
  "settings.cancelTerms.intro": "Ini adalah ketentuan untuk langganan Luminous StockHaven berbayar. Penagihan langganan situs web dilakukan melalui Stripe. Anda dapat membatalkan langganan Anda sendiri kapan saja menggunakan tombol Batalkan Berlangganan di bawah — tidak diperlukan persetujuan staf. Permintaan pembatalan dan pengembalian dana juga dapat ditangani melalui kontak resmi dukungan pelanggan, theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Anda dapat membatalkan langganan Anda sendiri kapan saja. Tidak diperlukan persetujuan staf. Perpanjangan di masa mendatang berhenti hanya setelah penyedia penagihan mengonfirmasi pembatalan.",
  "settings.cancelTerms.noApprovalTitle": "Membatalkan tanpa persetujuan:",
  "settings.cancelTerms.paymentBody": "Untuk uji coba berbayar, uji coba tujuh hari memerlukan metode pembayaran saat mendaftar. Kecuali dibatalkan dalam batas waktu pembatalan uji coba yang berlaku, paket bulanan yang dipilih akan dikenakan biaya secara otomatis setelah uji coba. Harga, tanggal penagihan pertama, dan batas waktu pembatalan khusus penyedia harus ditampilkan saat pendaftaran. Penagihan percobaan dilakukan melalui Stripe.",
  "settings.cancelTerms.paymentTitle": "Metode pembayaran dan perpanjangan otomatis:",
  "settings.cancelTerms.remainingBody": "Jika Anda telah membayar untuk suatu periode penagihan, Anda dapat mempertahankan akses hingga tanggal pembayaran terverifikasi tersebut. Pengakhiran lebih awal memerlukan konfirmasi penyedia yang sesuai dan penanganan pengembalian dana yang berlaku. Akses uji coba gratis berakhir sesuai dengan tanggal penghentian uji coba yang dikonfirmasi oleh penyedia.",
  "settings.cancelTerms.remainingTitle": "Akses yang tersisa:",
  "settings.cancelTerms.storesBody": "Jika Anda pernah berlangganan melalui Google Play atau Apple App Store, langganan Anda ditagih dan dikelola oleh toko tersebut. Anda mungkin perlu membatalkannya langsung di bagian langganan di Google atau akun Apple yang sama yang digunakan untuk berlangganan. Membatalkan langganan situs web terpisah, mencopot pemasangan aplikasi ini, atau meminta penghapusan akun Luminous StockHaven tidak secara otomatis membatalkan langganan yang ditagih di toko. Periksa tanda terima pembelian Anda untuk mengonfirmasi siapa yang menagih Anda.",
  "settings.cancelTerms.storesTitle": "Langganan Google Play dan Apple App Store (jika Anda pernah berlangganan melalui toko):",
  "settings.cancelTerms.title": "Syarat & Ketentuan Pembatalan",
  "settings.cancelTerms.trialBody": "Uji coba tujuh hari hanya dapat digunakan satu kali per pelanggan yang memenuhi syarat. Membatalkan uji coba atau berlangganan tidak memberikan uji coba berikutnya; pelanggan yang kembali harus memilih langganan berbayar.",
  "settings.cancelTerms.trialTitle": "Satu uji coba gratis:",
