  "settings.switcher.newDescription": "Setiap bisnis menyimpan produk, lokasi, pemasok, dan pesanan pembeliannya sendiri. Tidak ada yang dibagi di antara mereka.",
  "settings.switcher.newTitle": "Bisnis baru",
