  "settings.switcher.upgrade": "Tingkatkan",
  "settings.title": "Pengaturan",
  "settings.trial.cancelKeeps": "Pembatalan selama uji coba akan memakan waktu 7 hari penuh — akses berakhir pada {date}, dan Anda tidak akan dikenakan biaya.",
  "staff.access.noSeatBody": "Akun Anda tidak memiliki kursi staf untuk bisnis ini, sehingga stoknya tetap ditutup. Minta pemilik untuk menambahkan Anda di Staf & peran.",
  "staff.access.noSeatTitle": "Bisnis ini tidak terbuka untuk login Anda",
  "staff.access.pendingBody": "Bisnis ini memiliki undangan untuk email Anda yang belum diaktifkan. Minta pemilik untuk mengatur status staf Anda menjadi aktif. Tidak ada apa pun di sini yang terlihat sampai saat itu.",
  "staff.access.pendingTitle": "Undangan Anda belum aktif",
  "staff.access.signOut": "Keluar",
  "staff.access.suspendedBody": "Administrator telah menangguhkan akun staf ini untuk bisnis yang aktif. Minta mereka untuk membuat Anda kembali aktif, lalu masuk lagi.",
  "staff.access.suspendedTitle": "Akses Anda dijeda",
  "staff.addFirst": "Tambahkan anggota staf pertama",
  "staff.addMember": "Tambahkan anggota staf",
  "staff.emptyBody": "Tambahkan seseorang, beri mereka peran dan izin yang menyertainya, dan mereka diundang melalui email untuk masuk ke bisnis ini.",
  "staff.emptyTitle": "Belum ada staf",
  "staff.eyebrow": "Tim",
  "staff.how.p1": "Setiap anggota memiliki peran dan daftar izinnya masing-masing, sehingga Anda dapat memulai dari sebuah peran dan mengubah satu hal tanpa membuat peran baru. Mengedit peran tidak akan menulis ulang anggota yang sudah ada di dalamnya — buka anggota untuk menerapkan kembali peran defaultnya.",
  "staff.how.p2": "Peran khusus adalah fitur Bisnis: Essentials menggunakan lima peran bawaan (Pemilik, Manajer, Petugas Stok, Petugas Penjualan, Penampil).",
  "staff.how.p3": "Undangan dikirim melalui email. Seorang anggota hanya dapat masuk setelah mereka menyetujuinya, dan menghapus seseorang dari daftar ini tidak menghapus akun aplikasinya.",
  "staff.how.p4": "Toko adalah lokasi tempat seseorang ditugaskan. Itu dicatat di kartu mereka; apa yang bisa mereka buka masih ditentukan oleh peran dan izin mereka.",
  "staff.how.p5": "Izin menentukan apa yang dapat dibuka setiap orang: item menu di luar peran mereka disembunyikan, dan alamat yang diblokir menampilkan pemberitahuan “tidak sesuai peran Anda” alih-alih halaman. Perubahan akan diterapkan saat orang tersebut memuat aplikasi lagi; menangguhkan anggota akan mengunci mereka sepenuhnya.",
  "staff.how.p6": "Administrator dapat melihat dan mengubah semua data, mengelola pengguna dan peran aplikasi, dan tidak pernah dibatasi oleh peran staf. Seseorang yang tidak memiliki catatan staf — pemilik bisnis baru — memiliki akses penuh.",
  "staff.howTitle": "Bagaimana staf dan peran bekerja",
