  "auth.sameEmailNotice": "Sudah punya aplikasi kami dari Google Play atau App Store? Gunakan email yang sama di sini — email yang Anda gunakan untuk masuk ke aplikasi — agar toko dan inventaris Anda ikut bersama Anda. Email yang berbeda memulai etalase yang benar-benar baru dan kosong.",
