  "recovery.subtitle": "Kehilangan akses ke email tempat akun Anda berada? Kunci cadangan Anda dapat membawa Anda kembali ke toko Anda.",
  "recovery.remembered": "Ternyata ingat lagi?",
  "recovery.backToLogin": "Kembali ke masuk",
  "recovery.genericError": "Terjadi kesalahan. Silakan coba lagi.",
  "recovery.emailLabel": "Email akun Anda",
