  "rewards.mine.empty": "Belum ada hadiah. Saat manajer atau pemilik memberi Anda satu, hadiah itu tiba di sini.",
  "rewards.mine.from": "Dari {name}",
  "rewards.mine.title": "Hadiah saya",
  "rewards.redeem.done": "Hadiah ditandai sebagai telah digunakan.",
