  "rewards.status.active": "Siap digunakan",
  "rewards.status.redeemed": "Telah digunakan",
  "rewards.status.void": "Batal",
  "rewards.subtitle": "Ucapkan terima kasih dengan hadiah — persen potongan, kartu hadiah, atau apa pun yang Anda jelaskan.",
  "rewards.title": "Hadiah & insentif",
  "rewards.value.giftCard": "Kartu hadiah {value}",
  "rewards.value.percentOff": "Potongan {percent}% di toko",
  "rewards.void": "Batalkan",
  "rewards.voided": "Hadiah dibatalkan.",
  "workforce.tab.rewards": "Hadiah",
  "training.lessons.mgr-give-rewards.step1": "Buka Tenaga Kerja dan ketuk Hadiah. Pilih anggota tim, lalu jenisnya: persen potongan di toko, kartu hadiah, atau sesuatu yang lain yang Anda jelaskan dengan kata-kata Anda sendiri.",
  "training.lessons.mgr-give-rewards.step2": "Beri hadiah nama singkat dan catatan jika Anda mau. Orang tersebut mendapat lonceng segera, dan hadiah menunggu di Hadiah saya mereka dengan kodenya sendiri.",
  "training.lessons.mgr-give-rewards.step3": "Batasnya, berdasarkan desain: Anda memberi hadiah kepada STAF saja. Anda tidak dapat memberi hadiah kepada diri sendiri atau manajer lain — memberi hadiah kepada manajer adalah keputusan pemilik, dan aplikasi akan menolaknya dengan jelas.",
  "training.lessons.mgr-give-rewards.step4": "Di kasir, ketik kode yang ditunjukkan anggota tim kepada Anda dan tandai sebagai telah digunakan — setiap kode berfungsi sekali. Anda dapat membatalkan hadiah yang Anda berikan jika rencana berubah; hadiah pemilik adalah milik pemilik untuk dibatalkan.",
  "training.lessons.mgr-give-rewards.title": "Memberi hadiah kepada staf Anda",
  "training.lessons.owner-give-rewards.step1": "Hadiah berada di Tenaga Kerja, pada tab Hadiah, dan hanya untuk paket Business — pada Essentials, tab menunjukkan pintu terkunci, agar tim Anda dapat melihat apa yang ditawarkan paket yang lebih besar.",
  "training.lessons.owner-give-rewards.step2": "Anda dapat memberi hadiah kepada SIAPA PUN di tim — staf dan manajer sama-sama. Pilih orangnya, lalu jenisnya: persen potongan di toko (persen apa pun yang Anda pilih), kartu hadiah ke mana saja, atau insentif apa pun yang Anda jelaskan dengan kata-kata Anda sendiri.",
  "training.lessons.owner-give-rewards.step3": "Hadiah tiba dengan kode sekali pakainya sendiri dan membunyikan lonceng orang tersebut. Mereka menunjukkan kode di kasir; pemilik atau manajer mengetiknya untuk menandainya telah digunakan.",
  "training.lessons.owner-give-rewards.step4": "Slip hadiah yang dicetak atau dibagikan hanya memuat nama bisnis ANDA — tidak pernah nama aplikasi. Itu adalah ucapan terima kasih toko Anda, bukan iklan.",
  "training.lessons.owner-give-rewards.title": "Memberi hadiah (paket Business)",
  "training.lessons.owner-rewards-oversight.step1": "Manajer Anda juga dapat memberi hadiah — hanya kepada staf. Aplikasi menolak manajer yang memberi hadiah kepada diri mereka sendiri atau manajer lain; memberi hadiah kepada manajer selalu adalah keputusan Anda.",
  "training.lessons.owner-rewards-oversight.step2": "Anda melihat setiap hadiah di bisnis dalam Riwayat hadiah: siapa yang memberikannya, siapa yang mendapatkannya, dan apakah hadiah itu siap, telah digunakan, atau batal. Manajer hanya melihat hadiah yang mereka berikan dan yang mereka terima.",
  "training.lessons.owner-rewards-oversight.step3": "Anda dapat membatalkan hadiah apa pun, termasuk yang diberikan manajer Anda. Manajer dapat membatalkan hadiah mereka sendiri, tetapi tidak pernah milik Anda.",
  "training.lessons.owner-rewards-oversight.step4": "Setiap kode berfungsi tepat sekali, dan hadiah yang dibatalkan tidak pernah dapat digunakan — riwayat selalu menunjukkan bagaimana suatu hadiah berakhir.",
  "training.lessons.owner-rewards-oversight.title": "Mengawasi hadiah: pemberian manajer Anda",
  "training.lessons.staff-your-rewards.step1": "Saat manajer atau pemilik memberi Anda hadiah, lonceng Anda berbunyi. Buka Tenaga Kerja dan ketuk Hadiah untuk melihatnya di bawah Hadiah saya.",
  "training.lessons.staff-your-rewards.step2": "Setiap hadiah memiliki kodenya sendiri. Simpan untuk diri Anda sendiri — siapa pun yang menunjukkan kode di kasir adalah orang yang menggunakan hadiah itu.",
  "training.lessons.staff-your-rewards.step3": "Untuk menggunakannya, tunjukkan kode saat Anda membeli. Orang di kasir mengetiknya dan menandainya telah digunakan — setiap kode berfungsi tepat sekali.",
  "training.lessons.staff-your-rewards.step4": "Hadiah adalah suguhan paket Business. Jika toko Anda tidak menggunakan Business, tab Hadiah menunjukkan pintu terkunci sebagai gantinya — itu adalah paketnya, bukan kesalahan.",
  "training.lessons.staff-your-rewards.title": "Hadiah Anda: menemukan kode Anda dan menggunakannya",
  "training.module.rewards": "Hadiah & insentif",
